import initialData from './initial-data.js';
import { mapGiftCardRedeemedFields } from '../shared/gift-card-redeemed-fields.js';

export default class GiftCardRedeemed {
    constructor(details) {
        this.details = details || {};
    }

    toSegment() {
        return {
            event: 'Gift Card Redeemed',
            properties: mapGiftCardRedeemedFields({
                source: 'checkout',
                customer_id: initialData.get('customer.id'),
                store_id: initialData.get('store.id'),
            }, this.details),
        };
    }
}
